/**
 * Cloudflare Worker entry: the Next.js app (built by OpenNext into .open-next/), plus
 *  • the server functions at /.netlify/functions/<name> (see src/lib/server/functions.ts),
 *  • the daily territory decay (cron in wrangler.jsonc),
 *  • www.worfix.site → worfix.site,
 *  • v5: app-link files for the Android/iOS app and the daily streak reminder (cron).
 * Static files are served by Cloudflare before this code runs, except route-group chunks (below).
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import nextApp from "./.open-next/worker.js";
import bracketChunks from "./.open-next/bracket-chunks.json";
import { FUNCTIONS } from "./src/lib/server/functions";
import { runTerritoryDecay } from "./src/lib/server/handlers";
import { runStreakReminders } from "./src/lib/server/push";
import { runMissionReminders } from "./src/lib/server/v6";

/**
 * v5 app links: worfix.site links open in the WORFIX app. SHA-256 fingerprints of the Android signing
 * certificates (the upload key; add the Play App Signing key in ANDROID_CERT_SHA256, comma separated).
 */
const ANDROID_CERTS = ["18:DE:3C:E4:6A:C4:16:A3:FE:A1:D5:33:8B:D1:89:9D:B5:AF:8E:BD:E3:E9:C7:74:05:07:6D:A7:64:17:8E:FA"];
const APP_PATHS = ["/app", "/app/*", "/org/*", "/missions/*", "/login", "/register"];

function wellKnown(path: string, env: Env): Response | null {
  const headers = { "content-type": "application/json", "cache-control": "public, max-age=3600" };
  if (path === "/.well-known/assetlinks.json") {
    const extra = String(env.ANDROID_CERT_SHA256 ?? "").split(",").map((s) => s.trim()).filter(Boolean);
    return new Response(JSON.stringify([{
      relation: ["delegate_permission/common.handle_all_urls"],
      target: { namespace: "android_app", package_name: "site.worfix.app", sha256_cert_fingerprints: [...ANDROID_CERTS, ...extra] },
    }]), { headers });
  }
  if (path === "/.well-known/apple-app-site-association" || path === "/apple-app-site-association") {
    const team = String(env.APPLE_TEAM_ID ?? "").trim();
    if (!team) return new Response("Not found", { status: 404 });
    const appID = `${team}.site.worfix.app`;
    return new Response(JSON.stringify({
      applinks: { details: [{ appIDs: [appID], components: APP_PATHS.map((p) => ({ "/": p })) }] },
      webcredentials: { apps: [appID] },
    }), { headers });
  }
  return null;
}

type Env = Record<string, unknown>;
interface Ctx { waitUntil(p: Promise<unknown>): void; passThroughOnException?(): void }

/** Exposes the Worker's vars and secrets as process.env, where the shared server code reads them. */
function useEnv(env: Env) {
  for (const [k, v] of Object.entries(env)) if (typeof v === "string") process.env[k] = v;
}

const FN = /^\/\.netlify\/functions\/([a-z-]+)\/?$/;

export default {
  async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
    const url = new URL(request.url);
    if (url.hostname.startsWith("www.")) {
      url.hostname = url.hostname.slice(4);
      return Response.redirect(url.toString(), 301);
    }
    if (url.pathname.startsWith("/_next/static/chunks/app/")) {
      // Chunks named "[id]" / "(group)" are embedded (see scripts/embed-bracket-chunks.mjs): the asset
      // server redirects those names in a loop. Every other chunk is a normal asset.
      let key = url.pathname;
      try { key = decodeURIComponent(key); } catch { /* keep as is */ }
      const body = (bracketChunks as Record<string, string>)[key];
      if (body !== undefined) {
        const type = key.endsWith(".css") ? "text/css" : "text/javascript";
        return new Response(request.method === "HEAD" ? null : body, {
          headers: { "content-type": `${type}; charset=utf-8`, "cache-control": "public, max-age=31536000, immutable", "x-content-type-options": "nosniff" },
        });
      }
      return (env.ASSETS as { fetch(r: Request): Promise<Response> }).fetch(request);
    }
    if (url.pathname.startsWith("/.well-known/") || url.pathname === "/apple-app-site-association") {
      const r = wellKnown(url.pathname, env);
      if (r) return r;
    }
    const m = FN.exec(url.pathname);
    if (m) {
      const fn = FUNCTIONS[m[1]];
      if (!fn) return new Response("Not found", { status: 404 });
      if (request.method !== fn.method) return new Response("Method not allowed", { status: 405 });
      useEnv(env);
      return fn.run(request);
    }
    return nextApp.fetch(request, env, ctx);
  },

  async scheduled(event: { cron?: string }, env: Env, ctx: Ctx) {
    useEnv(env);
    // 13:00 UTC (18:00 in Tashkent): "your streak ends today" pushes; every other cron: the territory decay.
    if (event.cron === "0 13 * * *") ctx.waitUntil(runStreakReminders().then((r) => console.log("[streak-reminders]", JSON.stringify(r))));
    // v6: "ending soon" mission reminders, every 30 minutes
    else if (event.cron === "*/30 * * * *") ctx.waitUntil(runMissionReminders().then((r) => console.log("[mission-reminders]", JSON.stringify(r))));
    else ctx.waitUntil(runTerritoryDecay().then((r) => console.log("[territory-decay]", JSON.stringify(r))));
  },
};
